// The first Magic roster: 4 peoples x 3 subclasses x 3 specializations (36). Replaced by 12 characters (the subclasses themselves).
ARCHIVE.magic36 = {"frequencyinterceptors":{"leaf":{"id":"frequencyinterceptors","name":"Frequency Interceptors","icon":"radio","role":"combat","tagline":"Find the frequency.","summary":"Combat disruptors who tune into an enemy's spell the instant it is cast and cancel it. Frequency Interceptors counter, jam and answer with a resonance beam matched to the target.","lore":"Formerly known as the Dial-Turners, they work from a radio-staff and a dial gauntlet, and keep a log of every frequency they have ever cancelled.","strengths":["Counterspells and jamming of enemy casters","Strong damage against targets they have tuned"],"weaknesses":["Needs a moment to tune","Fragile if interrupted"],"abilities":["Tune In: find a target's resonance","Counter-Burst: cancel a spell as it is cast","Resonance Beam: heavy damage on a tuned target"],"gear":"Radio staff, dial gauntlet, antenna hat, shortwave charm","look":"Tall, elegant wizard in a structured green coat and an antenna-crowned hat, a radio-topped staff in one hand and a gold-ringed dial gauntlet crackling in the other.","pal":["#5a844c","#f72585","#ffd60a"]},"meta":{"type":"controller","physique":"tall and elegant","size":"medium","move":"grounded","who":"a woman in her forties, dark-skinned, with long white braids"},"spec":{"w":"wizard in a structured green coat and an antenna-crowned hat, a radio-shaped staff in one hand and a gold-ringed dial gauntlet on the other forearm, a shortwave charm necklace","p":"a radio station room with a huge shortwave set with glowing dials, a mixing desk, an antenna array outside the window, a wall of tubes"},"cast":{"gender":"Female","ethnicity":"Black American heritage, American","expression":"poised, razor-sharp focus","pose":"radio staff held up, dial gauntlet thrust forward crackling"}},"broadcasttheorists":{"leaf":{"id":"broadcasttheorists","name":"Broadcast Theorists","icon":"antenna","role":"support","tagline":"Louder is a theory.","summary":"Long-range theorists who amplify signals and, with them, other people's magic. Broadcast Theorists extend range, carry buffs across the field and make every ally's spell travel farther.","lore":"They publish papers on the theory of amplification and then demonstrate them at volume. A Theorist in your party means your spells arrive before the enemy's.","strengths":["Extends the range and reach of allies' spells","Spreads buffs across a wide area"],"weaknesses":["Almost no direct offense","Their equipment is bulky and loud"],"abilities":["Amplify: increase an ally's spell range and power","Carrier Wave: spread a buff to everyone in a line","Relay: cast through an ally's position"],"gear":"Parabolic ear-horn, amplifier pack, signal slate, long coat","look":"Older, silver-mustached wizard in a long structured coat with a parabolic ear-horn raised to the sky and a boxy amplifier on the back, one hand writing on a slate.","pal":["#356e1d","#2a9d8f","#fff3c4"]},"meta":{"type":"enchanter","physique":"broad-shouldered and slightly stooped","size":"medium","move":"grounded","who":"a man in his sixties of South Asian-inspired features, silver mustache"},"spec":{"w":"wizard in a long structured coat with a parabolic ear-horn raised overhead, a boxy amplifier pack on the back, a slate and chalk in the other hand","p":"a rooftop broadcast array with a giant parabolic dish, a transmitter tower, a field of cables and a signal shed"},"cast":{"gender":"Male","ethnicity":"South Asian-inspired heritage, Indian","expression":"delighted, lecturing eyebrows","pose":"ear-horn raised to the sky, slate and chalk in the other hand"}},"deadbanddecoders":{"leaf":{"id":"deadbanddecoders","name":"Deadband Decoders","icon":"scroll-text","role":"support","tagline":"Nothing hides in the noise.","summary":"Analysts who find the hidden transmissions between the stations. Deadband Decoders reveal concealed things, strip magical interference from allies and expose what an enemy is casting.","lore":"They listen to the silence between channels, which is where most secrets travel. Decoders are quiet people who always seem to know what you are about to say.","strengths":["Reveals hidden enemies, traps and spells","Cleanses magical interference from allies"],"weaknesses":["Little offense","Needs time to decode"],"abilities":["Decode: reveal hidden things in an area","Noise Floor: strip interference and status effects","Cipher Break: expose an enemy's next spell"],"gear":"Studio headphones, decoder wheel, spectrum lens, notebook","look":"Young, lithe wizard in a cropped structured jacket and big headphones, a brass decoder wheel in one hand and a spectrum lens held up to one eye.","pal":["#208a1d","#ffd166","#ebffc0"]},"meta":{"type":"support","physique":"lithe and narrow","size":"medium","move":"agile","who":"a nonbinary young adult of East Asian-inspired features, short bleached hair"},"spec":{"w":"wizard in a cropped structured jacket and big studio headphones, a brass decoder wheel in one hand and a spectrum lens held to one eye, a notebook at the belt","p":"a dim monitoring room with a wall of oscilloscopes, a rack of radio receivers, a spectrum display and a tangle of antenna cables"},"cast":{"gender":"Nonbinary","ethnicity":"East Asian-inspired heritage, Japanese","expression":"intent, squinting through the lens","pose":"turning the decoder wheel with one hand, lens at the eye"}},"runeplateengineers":{"leaf":{"id":"runeplateengineers","name":"Runeplate Engineers","icon":"shield","role":"combat","tagline":"Wards, but with tolerances.","summary":"Armorers who etch protective circuits into plate. Runeplate Engineers stand in the line in enchanted armor, throw up wards that follow a formula and harden whatever they touch.","lore":"Their armor is engraved with a pattern so precise that blows slide along the lines instead of landing. They check the tolerances before every fight.","strengths":["Superb protective wards and enchanted armor","Strengthen allies' armor mid-fight"],"weaknesses":["Slow to reconfigure wards","Heavy kit limits mobility"],"abilities":["Ward Plate: raise a protective circuit shield","Grounding Line: absorb and redirect a hit","Armor Etch: enchant an ally's armor for a turn"],"gear":"Runeplate pauldrons, tablet gauntlet, etching stylus, wrench","look":"Broad, strong wizard in layered armor etched with glowing circuit-lines, a tablet gauntlet on one forearm and a stylus in the other hand, feet planted wide.","pal":["#f14fea","#3a86ff","#e4ffda"]},"meta":{"type":"tank","physique":"broad and heavily built","size":"large","move":"grounded","who":"a woman in her fifties of Polynesian-inspired features, strong arms"},"spec":{"w":"wizard in layered armor etched with circuit lines, runeplate pauldrons, a tablet gauntlet on one forearm and a stylus in the other hand","p":"an armorer's forge with an anvil, racks of rune-etched plate, a circuit-etching bench and a stack of copper ingots"},"cast":{"gender":"Female","ethnicity":"Polynesian-inspired heritage, Tongan","expression":"stern, craftsperson's frown","pose":"planted wide with the tablet gauntlet raised, stylus glowing"}},"capacitorduelists":{"leaf":{"id":"capacitorduelists","name":"Capacitor Duelists","icon":"bolt","role":"combat","tagline":"Store it. Spend it all.","summary":"Duelists who charge their blades and bracers between exchanges. Capacitor Duelists bank energy during a parry and release it in a rapid string of discharges.","lore":"Their rapiers are hollow and packed with coils. A good Duelist wins by timing: they hold the charge until the exact moment it ends the fight.","strengths":["Stored-energy burst damage","Fast, precise rapid discharges"],"weaknesses":["Weak when drained","Needs time to recharge between flurries"],"abilities":["Charge Store: bank energy from a parry","Discharge Thrust: release a string of strikes","Arc Riposte: counter an attack with lightning"],"gear":"Coil-hilt rapier, capacitor bracers, insulated gloves, short coat","look":"Lean young wizard in a sharp short coat mid-lunge, a coil-wrapped rapier extended and glowing capacitor bracers on both wrists.","pal":["#8283f7","#ff5d8f","#fff7c7"]},"meta":{"type":"fighter","physique":"lean and quick","size":"medium","move":"agile","who":"a young man in his twenties of Mexican-inspired features, sharp sideburns"},"spec":{"w":"wizard in a sharp short coat, a coil-hilt rapier in one hand, capacitor bracers on both wrists, insulated gloves","p":"a duel ring on a rooftop with a bank of tall capacitors, a coil tower arcing lightning and rubber safety mats"},"cast":{"gender":"Male","ethnicity":"Mexican heritage, Mexican","expression":"cocky, sparking grin","pose":"full lunge, coil-rapier extended with a discharge arc"}},"logicgatearchitects":{"leaf":{"id":"logicgatearchitects","name":"Logic-Gate Architects","icon":"puzzle","role":"combat","tagline":"If this, then that. Then that.","summary":"Battlefield engineers who lay down magical logic. Logic-Gate Architects place traps and barriers that trigger on conditions: an enemy crossing a line, two foes at once, a spell cast.","lore":"They draw their circuits in chalk and tile, and the battlefield becomes a program. They are never surprised, because they wrote the surprise.","strengths":["Conditional traps and barriers","Excellent area control"],"weaknesses":["Slow setup","A broken circuit disables the trap"],"abilities":["AND Gate: trigger when two enemies stand in the zone","NOT Gate: block a chosen spell type in an area","Latch: lock enemies in place until a condition is met"],"gear":"Drafting compass, circuit-tile satchel, chalk, structured long coat","look":"Tall, elderly wizard in a long structured coat covered in chalk diagrams, a drafting compass in one hand and a satchel of circuit-tiles open at the hip.","pal":["#505e39","#ff7b00","#eef6ff"]},"meta":{"type":"controller","physique":"tall and angular","size":"large","move":"grounded","who":"an elderly woman in her late sixties of Scandinavian-inspired features, cropped silver hair"},"spec":{"w":"wizard in a long structured coat covered in chalk diagrams, a drafting compass in one hand and an open satchel of circuit tiles at the hip","p":"a tiled courtyard laid out as a giant circuit board with raised gate-shaped walls, glowing logic traces and a chalk-marked floor"},"cast":{"gender":"Female","ethnicity":"Scandinavian heritage, Norwegian","expression":"calm, calculating","pose":"drawing a chalk circuit in the air with a compass, satchel open"}},"slimeslingalchemists":{"leaf":{"id":"slimeslingalchemists","name":"Slime-Sling Alchemists","icon":"frog","role":"combat","tagline":"Stick around.","summary":"Ranged alchemists who fire adhesive projectiles and enchanted gels. Slime-Sling Alchemists pin enemies to the floor, glue weapons to scabbards and turn a charge into a standstill. Home of the Sticky Wizard.","lore":"Sticky Wizard (created by Mike Mears) is the school's signature figure: a small, round, wide-eyed frog in an oversized wizard hat, hung with vials and goo-jars. Playful, bubbly and entirely capable, they fight with timing and sticky chemistry.","strengths":["Pins and immobilizes enemies at range","Setups that make every ally's hit land"],"weaknesses":["Short on raw damage","Gel runs out without refills"],"abilities":["Goo Shot: ranged adhesive that roots a target","Gluey Hat Trick: yank an enemy's weapon from their hands","Sticky Situation: coat an area so enemies move slowly"],"gear":"Oversized wizard hat, sling-staff, goo-jar bandolier, alchemy satchel","look":"Small, round, expressive frog wizard in a floppy oversized pointed hat, a goo-jar bandolier across the chest and a sling-staff aimed mid-shot, wide eyes and a confident grin.","pal":["#0de609","#ffd23f","#ff6b9d"]},"meta":{"type":"blaster","physique":"small and round","size":"small","move":"agile","who":"Sticky Wizard (created by Mike Mears): a small, round, expressive frog person with an oversized hat and a playful, capable manner"},"spec":{"w":"small round frog wizard in an oversized floppy pointed hat, a bandolier of goo jars across the chest, a sling-staff aimed mid-shot, wide eyes and a confident grin","p":"a flooded alchemy basement with bubbling goo vats, dripping pipes, glued-down furniture and shelves of jars"},"cast":{"gender":"Male","ethnicity":"N/A (frog person, Sticky Wizard)","expression":"cheerful, wide-eyed confidence","pose":"leaning into a sling-shot of goo, hat flopping"}},"ricochetprofessors":{"leaf":{"id":"ricochetprofessors","name":"Ricochet Professors","icon":"orbit","role":"combat","tagline":"Please do bounce off the walls.","summary":"Elastic lecturers who teach spells to rebound. Ricochet Professors reflect enemy magic, chain bouncing bolts and turn every wall in the room into part of the attack.","lore":"They hold their classes in squash courts. A Professor's chalkboard is always covered in angles of incidence, and so is every battlefield they have ever stood on.","strengths":["Reflects spells and chains bounces through groups","Superb in cramped rooms"],"weaknesses":["Needs walls to bounce from","Fragile in open ground"],"abilities":["Rebound: reflect a spell back at the caster","Chain Bounce: a bolt ricochets between enemies","Elastic Cane: knock an enemy into a wall"],"gear":"Tweed coat, bouncy rubber cane, elbow patches, round spectacles","look":"Older, stout toad wizard in a patched tweed coat and round spectacles, a bright rubber cane arcing mid-swing, chalk dust on the sleeves.","pal":["#056f57","#2ec4b6","#fff0d1"]},"meta":{"type":"fighter","physique":"stout and padded","size":"medium","move":"agile","who":"an older female toad professor in a tweed coat"},"spec":{"w":"stout toad wizard in a patched tweed coat and round spectacles, a bright rubber cane in one hand mid-swing, chalk dust on the sleeves","p":"a squash court lecture hall with scuff-marked walls, a chalkboard of angles, rubber balls and a bench of students' coats"},"cast":{"gender":"Female","ethnicity":"N/A (toad person)","expression":"stern and amused behind round spectacles","pose":"swinging a rubber cane in a bouncing arc"}},"googlyphresearchers":{"leaf":{"id":"googlyphresearchers","name":"Goo-Glyph Researchers","icon":"pen-tool","role":"combat","tagline":"Peer-reviewed, and slightly damp.","summary":"Researchers who stamp sticky runes onto the battlefield. Goo-Glyph Researchers lay traps and area-control glyphs that glue, slow and hold, then detonate when the data comes in.","lore":"They write their findings directly onto the floor in gel. A glyph that is still tacky is still live, which is the only warning anyone gets.","strengths":["Sticky runes for traps and area control","Stacks slows into stuns"],"weaknesses":["Setup time","Glyphs wash out in rain"],"abilities":["Glyph Stamp: place a sticky rune that slows","Cross-Link: connect two glyphs into a snare","Peer Review: detonate every glyph at once"],"gear":"Glyph stamps, gel pot, goggles, lab apron","look":"Slim young salamander wizard in goggles and a rolled-sleeve lab apron, a rune stamp in one hand and a pot of gel in the other, one glowing glyph stuck to the floor beside.","pal":["#db5b0a","#ffbe0b","#fff5da"]},"meta":{"type":"controller","physique":"slim and nimble","size":"small","move":"climbing","who":"a young gender-neutral salamander researcher"},"spec":{"w":"slim salamander wizard in goggles and a rolled-sleeve lab apron, a rune stamp in one hand and a pot of gel in the other","p":"a damp research lab with glyph-covered floor tiles, gel-filled tanks, a stamp rack and a sticky-wall specimen board"},"cast":{"gender":"Nonbinary","ethnicity":"N/A (salamander person)","expression":"eager, goggles pushed up","pose":"stamping a glowing glyph onto the floor with one hand"}},"myceliummothers":{"leaf":{"id":"myceliummothers","name":"Mycelium Mothers","icon":"mushroom","role":"support","tagline":"The network remembers every one of us.","summary":"Elder healers who weave a fungal network between allies. Mycelium Mothers link a party's wounds together and mend them through the web, a slow, steady regeneration nobody can cut.","lore":"Each Mother tends a living mat of mycelium older than most of her patients. She hums to it while she works.","strengths":["Healing networks that share damage across allies","Regenerates the party between fights"],"weaknesses":["Slow burst healing","Fire destroys the network"],"abilities":["Mycelial Web: link allies and spread their damage","Spore Bloom: heal everyone in a ring over time","Network Pulse: send healing along the web to any ally"],"gear":"Spore-jar basket, fungus-wrapped cane, mushroom-cap shawl, poultice pouch","look":"Stout elderly woman in a patchwork shawl dotted with mushroom caps, leaning on a fungus-wrapped cane with a basket of glowing spore jars on one arm.","pal":["#d0e2a3","#2f6f4f","#ffb4a2"]},"meta":{"type":"support","physique":"stout and round","size":"medium","move":"grounded","who":"an elderly Black woman in her seventies, gray locs under a mushroom shawl"},"spec":{"w":"stout elderly woman in a patchwork shawl dotted with mushroom caps, a fungus-wrapped cane in one hand and a basket of glowing spore jars on the other arm","p":"a factory floor furred with glowing mycelium, a long table of growing trays, a hanging rack of mushroom caps and old machine hulks"},"cast":{"gender":"Female","ethnicity":"Black American heritage, American (Georgia)","expression":"tender, knowing","pose":"cane planted, one hand raised over glowing spore jars"}},"blightbrewers":{"leaf":{"id":"blightbrewers","name":"Blightbrewers","icon":"flask","role":"combat","tagline":"A little rot goes a long way.","summary":"Alchemists who brew toxic mixtures and let them work. Blightbrewers fling flasks of blight that spread, rot armor and linger long after the throw.","lore":"Their cauldrons are dented fermentation tanks from a dead brewery. Every Blightbrewer keeps a ledger of what each strain does, and the best have named theirs.","strengths":["Heavy damage over time that spreads","Corrodes armor and cures"],"weaknesses":["Slow damage ramp","Needs ingredients to brew"],"abilities":["Blight Flask: a lobbed poison that spreads on contact","Rot Mist: corrode armor in an area","Ferment: make a lingering effect hit again"],"gear":"Flask bandolier, ladle, cap-brim hat, thick apron","look":"Lean man in a mushroom-cap hat and a thick stained apron mid-throw, a bandolier of green flasks across the chest and a ladle clipped to the belt.","pal":["#5989d4","#3d405b","#ffe66d"]},"meta":{"type":"blaster","physique":"lean and wiry","size":"medium","move":"grounded","who":"a man in his thirties of Indonesian-inspired features, a wide mushroom-cap hat"},"spec":{"w":"lean man in a mushroom-cap hat and a thick stained apron, a bandolier of green flasks across the chest, a ladle clipped to the belt, mid-throw","p":"a dead brewery with dented fermentation tanks, bubbling vats, rows of labeled flasks and a loading dock"},"cast":{"gender":"Male","ethnicity":"Indonesian heritage, Indonesian","expression":"cheerfully wicked grin","pose":"mid-throw with a green flask, ladle on the hip"}},"sporeveilshepherds":{"leaf":{"id":"sporeveilshepherds","name":"Sporeveil Shepherds","icon":"yarn","role":"combat","tagline":"The mist is on our side.","summary":"Stalkers who herd fungal familiars and fog. Sporeveil Shepherds blanket a battlefield in camouflaging spores, send mushroom familiars to harry enemies and strike from the cloud.","lore":"Their familiars are small, round and loyal. The fog they carry hides allies and hurts anyone who inhales it twice.","strengths":["Concealment and camouflage for the whole party","Fungal familiars that harass and distract"],"weaknesses":["Fragile if the fog is blown away","Familiars are slow"],"abilities":["Sporeveil: hide allies in a drifting cloud","Familiar Call: send a fungal companion at a target","Cap Strike: ambush from inside the fog"],"gear":"Spore-gourd censer, hook-knife, fungus-fringed cloak, familiar basket","look":"Young woman in a fungus-fringed cloak and wrapped boots, a spore-gourd censer trailing mist in one hand and a hook-knife in the other, a small mushroom familiar at her feet.","pal":["#134e7d","#f4d35e","#1f1d49"]},"meta":{"type":"assassin","physique":"slim and light-footed","size":"medium","move":"agile","who":"a young woman in her twenties of Brazilian-inspired features, curly hair"},"spec":{"w":"young woman in a fungus-fringed cloak and wrapped boots, a spore-gourd censer trailing mist in one hand and a hook-knife in the other","p":"a misty mushroom grove in a flooded parking garage, hanging fungal curtains, glowing caps on concrete pillars and drifting spores"},"cast":{"gender":"Female","ethnicity":"Brazilian heritage, Brazilian","expression":"alert, partly hidden by mist","pose":"crouched with the censer streaming fog, hook-knife low"}},"dialhexers":{"leaf":{"id":"dialhexers","name":"Dial-Hexers","icon":"radio","role":"combat","tagline":"Please hold. The curse is connecting.","summary":"Curse-casters who send hexes down enchanted radios. Dial-Hexers tune a curse to an enemy's name and broadcast it, and it follows them across the field.","lore":"They keep a shelf of radios, each tuned to a different grudge. A Dial-Hexer's curse can be answered but never switched off.","strengths":["Curses that follow a target across the battlefield","Weaken enemy defenses at range"],"weaknesses":["The curse is slow to take hold","Needs a working radio"],"abilities":["Tuned Curse: a hex that tracks one target","Dead Air: silence a target's spells","Spirit Static: a curse that spreads to nearby enemies"],"gear":"Hex radio, antenna wand, curse cassettes, shawl","look":"Woman in her thirties in a layered shawl and headscarf, a bent antenna wand raised in one hand and a battered hex radio on a strap at the hip, curse tapes tucked in a bandolier.","pal":["#b703ec","#00b4d8","#e4ffda"]},"meta":{"type":"controller","physique":"average and shawled","size":"medium","move":"grounded","who":"a woman in her mid-thirties of Lebanese-inspired features, dark headscarf"},"spec":{"w":"woman in a layered shawl and headscarf, a bent antenna wand in one hand and a battered hex radio on a strap, curse tapes tucked in a bandolier","p":"a cluttered radio shack with a wall of dead radios on shelves, a hex-tuned dial board, a table of curse tapes and a window of antennas"},"cast":{"gender":"Female","ethnicity":"Lebanese heritage, Lebanese","expression":"smoldering, lips moving in a murmur","pose":"antenna wand pointing out, radio held against the hip"}},"effigytinkerers":{"leaf":{"id":"effigytinkerers","name":"Effigy Tinkerers","icon":"baby","role":"combat","tagline":"Whatever happens to the doll happens to you.","summary":"Dollmakers who practice sympathetic magic with stitched and soldered effigies. Effigy Tinkerers link a figure to a foe and send the damage straight through.","lore":"Their workshops are cluttered with half-wired dolls and charms. A finished effigy has a speaker for a voice, and it says the target's name.","strengths":["Sympathetic magic that redirects damage","Charms that protect allies"],"weaknesses":["Setup time","Burning the effigy ends the spell"],"abilities":["Link Doll: share a target's damage with an effigy","Pin and Solder: stun a linked foe","Charm Guard: bind a protective charm to an ally"],"gear":"Stitched effigies, pin pouch, soldering needle, charm string","look":"Androgynous elder in a patched coat hung with small dolls and charms, a stitched effigy held up in one hand and a long soldering needle in the other.","pal":["#6a2936","#264653","#e9c46a"]},"meta":{"type":"caster","physique":"stocky and gnarled","size":"medium","move":"grounded","who":"a nonbinary elder of Inuit-inspired features, weathered face"},"spec":{"w":"androgynous elder in a patched coat hung with small dolls and charms, a stitched effigy held up in one hand and a soldering needle in the other","p":"a dollmaker's workshop with shelves of half-wired dolls, a soldering bench, jars of buttons and a sewing machine"},"cast":{"gender":"Nonbinary","ethnicity":"Inuit heritage, Canadian (Nunavut)","expression":"weathered, knowing smile","pose":"holding a stitched effigy up and a needle poised"}},"staticcharmers":{"leaf":{"id":"staticcharmers","name":"Static Charmers","icon":"bolt","role":"combat","tagline":"Haunted frequencies, handled.","summary":"Saboteurs who whisper to equipment. Static Charmers jam machines, make weapons misfire and bring haunted noise down on the enemy's gear.","lore":"Every device has a spirit, and a Charmer knows how to make it sulk. They are the reason an enemy radio only ever plays the one song.","strengths":["Disables enemy gear and devices","Makes weapons and tools misfire"],"weaknesses":["Weak against non-technological foes","Short range"],"abilities":["Haunted Hum: jam an enemy's weapon or device","Sulk: a device refuses to work for a turn","Static Chorus: area noise that disrupts casters and gear"],"gear":"Tuning-fork charm, copper-wire bracelet, cable cloak, pocket radio","look":"Slim person in a cable-fringed cloak with a copper-wire bracelet, one finger raised to coax static from a handheld radio, a tuning-fork charm swinging from the other hand.","pal":["#ccbdde","#ffb703","#3a0ca3"]},"meta":{"type":"assassin","physique":"slim and loose-limbed","size":"medium","move":"agile","who":"a slim person in their twenties of mixed heritage, a shaved head with a long braid"},"spec":{"w":"slim person in a cable-fringed cloak, a copper-wire bracelet, one hand coaxing static from a handheld radio and a tuning-fork charm in the other","p":"a junkyard of dead televisions and appliances stacked in walls, tangled cables, a flickering screen and a rusted fridge"},"cast":{"gender":"Nonbinary","ethnicity":"Mixed Pacific and African heritage, New Zealander","expression":"playful, eyes bright","pose":"coaxing static from a radio with one raised finger"}},"briarbinders":{"leaf":{"id":"briarbinders","name":"Briarbinders","icon":"tree-deciduous","role":"combat","tagline":"Come closer. The hedge insists.","summary":"Entanglers who grow thorn walls on command. Briarbinders root enemies in place, throw up bramble defenses and punish anyone who gets close.","lore":"They plant by walking the line. Where a Briarbinder has walked, a hedge is already thinking about growing.","strengths":["Entanglement and thorn defenses","Punishes enemies who attack in melee"],"weaknesses":["Slow to move","Weak to fire"],"abilities":["Bramble Bind: root enemies in thorns","Thorn Wall: raise a barrier that wounds","Hedge Reply: reflect damage from attackers"],"gear":"Thorn-wrapped staff, bark armor plates, seed pouch, hooded cloak","look":"Broad, weathered woman in a hooded cloak and bark armor plates, a thorn-wrapped staff planted in front of her and brambles coiling at her feet.","pal":["#053715","#f2cc8f","#bb4c2a"]},"meta":{"type":"tank","physique":"broad and weathered","size":"large","move":"grounded","who":"a woman in her fifties of Irish-inspired features, red-gray hair"},"spec":{"w":"broad weathered woman in a hooded cloak and bark armor plates, a thorn-wrapped staff planted in front of her, a seed pouch at the belt","p":"a reclaimed grove with a hedge-lined road, a thorn-covered archway, a half-buried car and tangled briars"},"cast":{"gender":"Female","ethnicity":"Irish heritage, Irish","expression":"grim, weather-beaten calm","pose":"staff planted as brambles surge from the ground"}},"rootbloodhealers":{"leaf":{"id":"rootbloodhealers","name":"Rootblood Healers","icon":"sprout","role":"support","tagline":"Medicine is a family recipe.","summary":"Herbal physicians who restore with plants. Rootblood Healers mend wounds with poultices, cure poisons with teas and make a body regrow what it lost.","lore":"Their remedies are passed down in whispered recipes. A Rootblood Healer will tell you the cure takes three days and a bitter taste, and be right.","strengths":["Regenerative medicine and plant-based restoration","Cleanses poisons and disease"],"weaknesses":["Slow, steady healing","Needs fresh herbs"],"abilities":["Poultice: heal over time","Bitter Tea: cleanse poison and disease","Regrow: restore a downed ally to their feet"],"gear":"Herb satchel, mortar and pestle, root-carved cane, woven sash","look":"Warm middle-aged man in a woven sash and a long herb-stained coat, a mortar and pestle in one hand and a root-carved cane in the other, a satchel of herbs at the hip.","pal":["#0d5faf","#f4a261","#fff7c7"]},"meta":{"type":"support","physique":"warm and sturdy","size":"medium","move":"grounded","who":"a man in his forties of West African-inspired features, close-cropped beard"},"spec":{"w":"warm man in a long herb-stained coat and a woven sash, a mortar and pestle in one hand and a root-carved cane in the other, a herb satchel at the hip","p":"a root-cellar clinic with hanging herb bundles, a long wooden table of poultices, a boiling kettle and shelves of tonic jars"},"cast":{"gender":"Male","ethnicity":"West African heritage, Senegalese","expression":"warm, reassuring","pose":"grinding herbs in a mortar, cane tucked under the arm"}},"ancestorgrovekeepers":{"leaf":{"id":"ancestorgrovekeepers","name":"Ancestor-Grove Keepers","icon":"leaf","role":"support","tagline":"Our dead are in the trees.","summary":"Spirit-speakers who commune with the ancestors in the grove. Ancestor-Grove Keepers ask the dead for protection and for luck, and the grove answers.","lore":"Each Keeper tends the one tree where their family's names are carved. They speak to it politely, and it sometimes speaks back.","strengths":["Spirit communion and protective rituals","Wards allies with the blessing of ancestors"],"weaknesses":["No offense","Needs a grove or a rooted sprig"],"abilities":["Ancestor's Blessing: a protective ward on every ally","Grove Whisper: ask the spirits what lies ahead","Name Carved: pull an ally back from a fatal hit"],"gear":"Carved ancestor staff, bone charms, sprig crown, long woven robe","look":"Elderly woman in a long woven robe and a sprig crown, a carved ancestor staff in both hands and bone charms rattling at the belt, eyes closed in prayer.","pal":["#d7c5a2","#1b4332","#fff7c7"]},"meta":{"type":"enchanter","physique":"frail and upright","size":"medium","move":"grounded","who":"an elderly woman in her eighties of Maori-inspired features, wise and serene"},"spec":{"w":"elderly woman in a long woven robe and a sprig crown, a carved ancestor staff held in both hands, bone charms at the belt","p":"a sacred grove with a huge carved ancestor tree, rows of name-carved stones, hanging charms and drifting leaves"},"cast":{"gender":"Female","ethnicity":"Maori heritage, New Zealander","expression":"serene, eyes closed in prayer","pose":"both hands on the carved staff, charms swaying"}},"abyssalpetitioners":{"leaf":{"id":"abyssalpetitioners","name":"Abyssal Petitioners","icon":"orbit","role":"combat","tagline":"Please accept our offering.","summary":"Supplicants who fire bolts of void. Abyssal Petitioners open dimensional wounds that bleed dark energy and keep them open until the patron is satisfied.","lore":"Each Petitioner carries a bowl for offerings and a mark on the palm where the pact was sealed. They kneel to cast, and never stop smiling.","strengths":["Void bolts and dimensional wounds","Strong ranged damage that ignores armor"],"weaknesses":["Costs health to cast","Fragile in close combat"],"abilities":["Void Bolt: a ranged blast that ignores armor","Dimensional Wound: a tear that bleeds damage over time","Offering: spend health to double the next bolt"],"gear":"Offering bowl, void-marked gauntlet, ritual-scar mantle, jagged crown","look":"Young man in a jagged mantle and asymmetric armor, a ritual mark glowing on one open palm and an offering bowl in the other, a thin crown of black spikes on his head.","pal":["#065255","#6a4c93","#caf9ff"]},"meta":{"type":"blaster","physique":"gaunt and tall","size":"medium","move":"grounded","who":"a young man in his twenties of Greek-inspired features, shaven head"},"spec":{"w":"young man in a jagged mantle and asymmetric armor, a ritual mark glowing on one open palm and a small offering bowl in the other, a thin crown of black spikes","p":"a ritual chamber with a floating black void-portal, an altar of offering bowls, chalk-circle floor and hanging chains"},"cast":{"gender":"Male","ethnicity":"Greek heritage, Greek","expression":"hollow, reverent smile","pose":"kneeling to cast, one palm glowing, offering bowl held out"}},"starlessheralds":{"leaf":{"id":"starlessheralds","name":"Starless Heralds","icon":"moon","role":"combat","tagline":"A sky with no stars is also an omen.","summary":"Heralds who carry cosmic omens and psychic corruption. Starless Heralds whisper the end of the world and the whispers take root in an enemy's mind.","lore":"They are the patron's voices in the world, each trailing a cloak that seems too dark to be cloth. People confess things around them.","strengths":["Psychic corruption and fear","Cosmic omens that weaken the whole enemy line"],"weaknesses":["Fragile body","Madness spreads to allies too"],"abilities":["Omen of Ruin: curse a target with a vision of defeat","Starless Whisper: corrupt an enemy's mind over time","Dread Herald: fear everyone near a chosen foe"],"gear":"Black star-chart scroll, omen bell, void cloak, ritual mask","look":"Tall, thin woman in a drifting black cloak with a mask etched with star charts, an omen bell in one hand and a long scroll unrolled in the other.","pal":["#bc07bf","#3d348b","#ddeeff"]},"meta":{"type":"caster","physique":"thin and willowy","size":"large","move":"grounded","who":"a woman in her thirties of Ethiopian-inspired features, very tall"},"spec":{"w":"tall thin woman in a drifting black cloak and a mask etched with star charts, an omen bell in one hand and a long scroll unrolled in the other","p":"an observatory ruin with an empty starless sky, a dead telescope, a toppled star-map table and a tolling bell tower"},"cast":{"gender":"Female","ethnicity":"Ethiopian heritage, Ethiopian","expression":"distant, mournful","pose":"ringing the omen bell with the scroll unrolled behind"}},"riftetheredsummoners":{"leaf":{"id":"riftetheredsummoners","name":"Rift-Tethered Summoners","icon":"waves","role":"combat","tagline":"I borrowed them. Do not look at them.","summary":"Summoners who hold doors open for extradimensional servants. Rift-Tethered Summoners bring a creature through a tether, command it for a short time and send it back before the bill arrives.","lore":"Each servant is tied to the Summoner by a visible cord of light. If the cord is cut, the servant remembers who called it.","strengths":["Summons temporary extradimensional servants","Strong crowd control and pressure"],"weaknesses":["Servants vanish if the Summoner is hit hard","Costly to maintain"],"abilities":["Open Tether: summon a servant through the rift","Command: direct the servant to strike or guard","Recall: pull the servant back and heal from its return"],"gear":"Tether rod, rift-lantern, ritual-chain belt, scar-marked cloak","look":"Heavyset older man in a scar-marked cloak and chain belt, a glowing tether rod in one hand and a rift lantern in the other, a faint cord of light trailing from the rod.","pal":["#836e49","#b2f7ef","#7209b7"]},"meta":{"type":"controller","physique":"heavyset and imposing","size":"large","move":"grounded","who":"an older man in his sixties of Filipino-inspired features, heavy build"},"spec":{"w":"heavyset man in a scar-marked cloak and a chain belt, a glowing tether rod in one hand and a rift lantern in the other","p":"a ritual yard with a glowing rift hovering above a summoning circle, a chain fence, a brazier and stacked offering crates"},"cast":{"gender":"Male","ethnicity":"Filipino heritage, Filipino","expression":"heavy-lidded, strained","pose":"holding the tether rod forward as a cord of light pulls taut"}},"pulsesacrificers":{"leaf":{"id":"pulsesacrificers","name":"Pulse-Sacrificers","icon":"flame","role":"combat","tagline":"Every heartbeat is a bullet.","summary":"Fighters who burn their own health for power. Pulse-Sacrificers convert each beat of the heart into a strike, and the closer to death they get, the harder they hit.","lore":"They wear a monitor on the chest that beeps when the sacrifice is in range. The fight is over when it flatlines, one way or the other.","strengths":["Health-powered attacks with huge damage near death","Terrifying momentum"],"weaknesses":["Dangerously low health","Wiped out by a good counter"],"abilities":["Burn the Pulse: spend health for massive damage","Flatline Strike: a heavy blow that costs the rest","Last Heartbeat: survive one fatal hit and strike back"],"gear":"Heart-monitor harness, wired gauntlets, jagged shoulder plate, cable-wrapped fists","look":"Broad woman in a jagged shoulder plate and a chest monitor, wired gauntlets raised in a boxing stance and a cable running from one wrist to the harness.","pal":["#46202b","#247ba0","#fff5da"]},"meta":{"type":"bruiser","physique":"broad and muscular","size":"large","move":"grounded","who":"a woman in her thirties of Samoan-inspired features, broad shoulders"},"spec":{"w":"broad woman in a jagged shoulder plate and a chest heart-monitor harness, wired gauntlets raised, a cable running from one wrist","p":"a boxing gym ruin with a ring, a wall of vital-sign monitors, a heavy bag and a flickering generator"},"cast":{"gender":"Female","ethnicity":"Samoan heritage, Samoan","expression":"wild, wide-eyed","pose":"boxing stance, wired gauntlets raised"}},"veincircuitreavers":{"leaf":{"id":"veincircuitreavers","name":"Vein-Circuit Reavers","icon":"heart","role":"combat","tagline":"Blood is a perfectly good conductor.","summary":"Skirmishers who run their veins through energy blades. Vein-Circuit Reavers heal with every strike, draining life from whatever they cut.","lore":"Their weapons are bladed capacitors tied into the wearer's arteries. A Reaver fights as if each wound they inflict is a wound they are repairing.","strengths":["Lifesteal and close-range energy weapons","Sustained damage through draining"],"weaknesses":["Short range","Burns through its own health when starved"],"abilities":["Siphon Cut: strike and heal from the damage","Arc Reave: a sweeping energy slash","Circuit Frenzy: gain attack speed with every kill"],"gear":"Vein-lit twin blades, wired arm sleeves, thorn plates, glowing circuit tattoos","look":"Lean man with glowing circuit tattoos along both arms, a bladed capacitor in each hand mid-slash, thorn plates jutting from the shoulders.","pal":["#b368c9","#7b47cf","#fff1e6"]},"meta":{"type":"fighter","physique":"lean and sinewy","size":"medium","move":"agile","who":"a man in his twenties of Vietnamese-inspired features, circuit tattoos"},"spec":{"w":"lean man with glowing circuit tattoos along both arms, a bladed capacitor in each hand mid-slash, thorn plates on the shoulders","p":"a dead power substation with a humming transformer, cable trenches, a generator hall and warning signs"},"cast":{"gender":"Male","ethnicity":"Vietnamese heritage, Vietnamese","expression":"feral, sinewy grin","pose":"crossed blades mid-slash with circuits blazing"}},"overloadmartyrs":{"leaf":{"id":"overloadmartyrs","name":"Overload Martyrs","icon":"bolt","role":"combat","tagline":"Stand clear.","summary":"Zealots who surge past the machine's limits. Overload Martyrs store a destructive charge in the body and release it all at once, usually ending themselves and everyone around.","lore":"They wear their last words on a strip of tape. It plays when the generator reaches critical.","strengths":["Unstable, enormous area discharges","Devastating when they choose the moment"],"weaknesses":["Often self-destructive","Useless once drained"],"abilities":["Overcharge: build a huge area blast over several turns","Martyr's Surge: detonate and take enemies with you","Meltdown: a short, wild blast that scorches everything"],"gear":"Reactor backpack, cable-wrapped arms, lead-lined vest, final-words tape","look":"Wiry older woman wearing a heavy reactor backpack and a lead-lined vest, both arms thrown wide with cables arcing and sparking, a small tape deck at the chest.","pal":["#4a3a5c","#43aa8b","#277da1"]},"meta":{"type":"blaster","physique":"wiry and fierce","size":"medium","move":"grounded","who":"an older woman in her sixties of Cuban-inspired features, wild gray hair"},"spec":{"w":"wiry older woman wearing a heavy reactor backpack and a lead-lined vest, both arms thrown wide with cables sparking, a small tape deck at the chest","p":"a cracked reactor hall with a glowing containment core, warning lights, scorched walls and a collapsed catwalk"},"cast":{"gender":"Female","ethnicity":"Cuban heritage, Cuban","expression":"ecstatic, frightening grin","pose":"both arms thrown wide as cables arc"}},"glasswalkassassins":{"leaf":{"id":"glasswalkassassins","name":"Glasswalk Assassins","icon":"mirror","role":"combat","tagline":"I'll be right behind you. I'm in the window.","summary":"Killers who step through reflections. Glasswalk Assassins vanish into one surface and step out of another, appearing behind a target, then are gone.","lore":"Their blades are shards of mirror. A Glasswalker's name is never said in a reflective room.","strengths":["Reflection-based repositioning and ambush","Extremely hard to pin down"],"weaknesses":["Needs a reflective surface nearby","Fragile"],"abilities":["Glasswalk: step between any two reflections","Shard Strike: a blade of mirror that ignores guard","Hollow Reflection: leave a mirror image behind"],"gear":"Mirror-shard daggers, reflective half-mask, glass-panel coat, silver gloves","look":"Slim man in a coat of mirrored glass panels and a reflective half-mask, a mirror-shard dagger in each hand, caught mid-step as if emerging from the air.","pal":["#00343e","#0077b6","#f72585"]},"meta":{"type":"assassin","physique":"slim and quick","size":"medium","move":"phasing","who":"a man in his thirties of Persian-inspired features, a mirrored half-mask"},"spec":{"w":"slim man in a coat of mirrored glass panels and a reflective half-mask, a mirror-shard dagger in each hand, caught mid-step","p":"a hall of broken mirrors and dead screens, a shattered storefront window, a mirror-lined corridor and glass shards on the floor"},"cast":{"gender":"Male","ethnicity":"Persian heritage, Iranian","expression":"impassive, only the eyes visible","pose":"stepping out of a reflection, dagger low"}},"shardbounddoppelgangers":{"leaf":{"id":"shardbounddoppelgangers","name":"Shardbound Doppelgangers","icon":"puzzle","role":"combat","tagline":"Which of us is the real me?","summary":"Fighters who split into copies. Shardbound Doppelgangers fracture into temporary duplicate bodies that fight alongside them and shatter on a hit.","lore":"Each duplicate is a mirror shard wearing their face. A Doppelganger is never alone in a fight, even when they are.","strengths":["Temporary duplicate bodies that fight and decoy","Excellent at overwhelming single targets"],"weaknesses":["Duplicates are fragile","Costs health per copy"],"abilities":["Fracture: split into two bodies","Hall of Mirrors: surround an enemy with copies","Shatter Swap: swap places with a copy as it breaks"],"gear":"Cracked-glass sword, shard crown, split-colored coat, silver rings","look":"Androgynous fighter in a coat split in two colors with a crown of mirror shards, a cracked-glass sword raised and two faint copies mirrored behind.","pal":["#4c5788","#ffd166","#3a86ff"]},"meta":{"type":"fighter","physique":"androgynous and balanced","size":"medium","move":"agile","who":"an androgynous adult of ambiguous heritage, split-colored hair"},"spec":{"w":"androgynous fighter in a coat split in two colors with a crown of mirror shards, a cracked-glass sword raised, silver rings","p":"a funhouse hall of fractured mirrors with a cracked glass floor, a mirror maze wall and a smashed vanity"},"cast":{"gender":"Nonbinary","ethnicity":"Ambiguous mixed heritage","expression":"calm, mirrored smirk","pose":"sword raised in one hand, other hand splayed as copies echo"}},"lookingglassprophets":{"leaf":{"id":"lookingglassprophets","name":"Looking-Glass Prophets","icon":"eye","role":"support","tagline":"I saw how this ends. Reversed.","summary":"Seers who show enemies what they fear in a mirror. Looking-Glass Prophets lay deceptive visions over a battlefield, reflect curses back at the caster and warn allies of what is coming.","lore":"They carry a hand mirror that shows tomorrow, slightly wrong. Their predictions are always true and never helpful in the way you hoped.","strengths":["Deceptive visions that mislead enemies","Reflects curses and warns allies"],"weaknesses":["Almost no offense","Their visions are sometimes wrong"],"abilities":["False Vision: make an enemy attack the wrong target","Reflected Curse: bounce a curse back at its caster","Reversed Omen: warn an ally and grant them a counter"],"gear":"Hand mirror, veil of mirrored beads, long robe, prophecy deck","look":"Poised older woman in a long robe and a veil of mirrored beads, a hand mirror held out at arm's length and a deck of prophecy cards in the other hand.","pal":["#450261","#ffd6a5","#00b4d8"]},"meta":{"type":"enchanter","physique":"poised and upright","size":"medium","move":"grounded","who":"an older woman in her sixties of Turkish-inspired features, a veil of mirrored beads"},"spec":{"w":"poised older woman in a long robe and a veil of mirrored beads, a hand mirror held at arm's length and a deck of prophecy cards in the other hand","p":"a fortune-teller's parlor with a huge gilded mirror, a crystal-less table, beaded curtains and a dead television altar"},"cast":{"gender":"Female","ethnicity":"Turkish heritage, Turkish","expression":"grave, half-veiled knowing","pose":"holding a hand mirror at arm's length, cards fanned"}},"secondslipduelists":{"leaf":{"id":"secondslipduelists","name":"Second-Slip Duelists","icon":"clock","role":"combat","tagline":"Let's try that again.","summary":"Duelists who rewind the last second. Second-Slip Duelists dodge a blow by being a step back from where it lands, then answer from where they were.","lore":"A Second-Slip never takes a clean hit. Watching them fight is watching someone replay a mistake until it works.","strengths":["Short-range rewinds and evasive combat","Superb counter-attack timing"],"weaknesses":["Short rewind range","Exhausting in long fights"],"abilities":["Slip Back: rewind to where you stood a second ago","Replay: repeat your last strike for free","Clean Cut: counter an attack that has already missed"],"gear":"Pocket watch, narrow blade, scuffed jacket, glowing second-hand charm","look":"Lean young man in a scuffed jacket mid-dodge with a narrow blade drawn, a faint ghost-copy of himself a half-step behind and a pocket watch swinging on its chain.","pal":["#8c606f","#fff3b0","#d00000"]},"meta":{"type":"fighter","physique":"lean and restless","size":"medium","move":"agile","who":"a young man in his twenties of Nigerian-inspired features, close-cropped hair"},"spec":{"w":"lean young man in a scuffed jacket mid-dodge, a narrow blade drawn, a pocket watch swinging on a chain","p":"a stopped-clock plaza with a giant frozen clock tower, a fountain of suspended droplets and a rain-slick street"},"cast":{"gender":"Male","ethnicity":"Nigerian heritage, Nigerian","expression":"restless, half-smiling","pose":"leaning out of a dodge with a ghost-copy a step behind"}},"afterimagerunners":{"leaf":{"id":"afterimagerunners","name":"Afterimage Runners","icon":"bolt","role":"combat","tagline":"I was already there.","summary":"Sprinters who outrun their own shadows. Afterimage Runners leave delayed images behind that strike a moment after the Runner has moved on.","lore":"They move too fast to see; the audience sees only the afterimages catching up. A Runner who stops for a breath arrives at the end of the fight on time.","strengths":["Accelerated movement and delayed strikes","Hard to catch and harder to pin"],"weaknesses":["Fragile if caught","Cannot sustain a sprint"],"abilities":["Blur Dash: sprint through enemies and strike","Afterimage Strike: a delayed second hit from where you were","Echo Run: leave decoys along your path"],"gear":"Running wraps, light-up trainers, slipstream scarf, athletic jacket","look":"Athletic woman in an open athletic jacket and a streaming scarf in a full sprint, three translucent afterimages trailing behind her, no weapons held.","pal":["#860145","#ffd23f","#fff7c7"]},"meta":{"type":"assassin","physique":"athletic and long-limbed","size":"medium","move":"agile","who":"a woman in her twenties of Kenyan-inspired features, a streaming scarf"},"spec":{"w":"athletic woman in an open athletic jacket and a streaming scarf, in a full sprint, running wraps on the hands, no weapons","p":"a long ruined track and field stadium with starting blocks, a scoreboard, floodlights and blurred stripes of light"},"cast":{"gender":"Female","ethnicity":"Kenyan heritage, Kenyan","expression":"exhilarated, hair streaming","pose":"full sprint with afterimages trailing behind"}},"paradoxwardens":{"leaf":{"id":"paradoxwardens","name":"Paradox Wardens","icon":"hourglass","role":"support","tagline":"Nobody gets hurt in this moment.","summary":"Guardians who freeze a patch of time. Paradox Wardens put an ally in stasis to save them from a hit, slow the enemy and hold the line in a moment that does not end.","lore":"A Warden carries a stopped clock. As long as it is stopped, the people inside the Warden's field are safe, and the ones outside are not.","strengths":["Localized time manipulation and defensive stasis","Saves allies from lethal damage"],"weaknesses":["Little offense","Stasis ends in a rush when the Warden falls"],"abilities":["Stasis: freeze an ally in time for a turn","Slow Field: cut enemy speed in an area","Held Breath: negate the next hit on every ally nearby"],"gear":"Stopped clock, hourglass staff, layered robe, sash of clock-hands","look":"Calm elderly man in a layered robe and a sash of clock-hands, an hourglass staff held upright in one hand and a stopped clock raised in the other, one palm out in a halting gesture.","pal":["#000491","#e63946","#6f9dc7"]},"meta":{"type":"support","physique":"tall and calm","size":"medium","move":"grounded","who":"an elderly man in his seventies of Chinese-inspired features, white beard"},"spec":{"w":"calm elderly man in a layered robe and a sash of clock hands, an hourglass staff in one hand and a stopped clock raised in the other","p":"a clockwork vault with huge frozen gears, a wall of stopped clocks, a floating hourglass and drifting suspended dust"},"cast":{"gender":"Male","ethnicity":"Chinese heritage, Chinese","expression":"serene, deep-set calm","pose":"one palm out in a halt, hourglass staff upright"}},"thoughtbladeadepts":{"leaf":{"id":"thoughtbladeadepts","name":"Thoughtblade Adepts","icon":"sparkles","role":"combat","tagline":"A thought is sharp enough.","summary":"Psychic blademasters who form weapons out of will. Thoughtblade Adepts hurl telekinetic blades and strike with the precision of a decision.","lore":"The blades look like faint knives of light. They do not exist until the Adept stops hesitating, and then they are very real.","strengths":["Telekinetic weapons and precise strikes","Strong against single targets"],"weaknesses":["Needs a clear mind","Breaks concentration when hit"],"abilities":["Will Blade: conjure a floating blade of thought","Mind's Edge: a precise strike that ignores armor","Telekinetic Throw: fling a foe or an object"],"gear":"Wrapped fists, plain headband, floating-blade focus, simple robe","look":"Slender man in a plain wrapped robe and a headband, one hand outstretched with three translucent thought-blades hovering around it, eyes shut in concentration.","pal":["#fe6eb5","#fee440","#d8fdff"]},"meta":{"type":"caster","physique":"slender and composed","size":"medium","move":"grounded","who":"a man in his thirties of Japanese-inspired features, a plain headband"},"spec":{"w":"slender man in a plain wrapped robe and a headband, one hand outstretched with a few thought-blades hovering near it, eyes shut","p":"a bare stone dojo with paper screens, a rack of practice weapons, a quiet pond and a single hanging lantern"},"cast":{"gender":"Male","ethnicity":"Japanese heritage, Japanese","expression":"composed, eyes shut","pose":"one hand extended with three thought-blades floating"}},"memorybreakers":{"leaf":{"id":"memorybreakers","name":"Memorybreakers","icon":"eye","role":"combat","tagline":"Forget I said that.","summary":"Mind-shatterers who unwind what an enemy remembers. Memorybreakers confuse, mislead and induce illusions, turning an enemy's own recollection against them.","lore":"They do not read thoughts; they erase the thread. A Memorybreaker's opponents often walk off the field wondering why they came.","strengths":["Confusion, illusion and mental disruption","Strips an enemy's buffs and plans"],"weaknesses":["No physical defense","Powerless against mindless foes"],"abilities":["Mind Fog: confuse enemies in an area","Break the Thread: erase an enemy's last action","False Memory: make an enemy attack their own ally"],"gear":"Cracked monocle, memory locket, long coat, soft gloves","look":"Elegant older woman in a long coat and soft gloves, a cracked monocle over one eye, one hand raised with fingers spread as if unthreading a spool in the air.","pal":["#ff8c42","#8338ec","#fcf6bd"]},"meta":{"type":"controller","physique":"elegant and slim","size":"medium","move":"grounded","who":"an older woman in her sixties of French-inspired features, a monocle"},"spec":{"w":"elegant older woman in a long coat and soft gloves, a cracked monocle over one eye, one hand raised with fingers spread as if unthreading a spool","p":"an archive of dusty photo albums and film reels, a projector throwing blank frames, a wall of framed faces with the glass cracked"},"cast":{"gender":"Female","ethnicity":"French heritage, French","expression":"arch, faintly amused","pose":"unthreading a spool in the air with splayed fingers"}},"willfieldguardians":{"leaf":{"id":"willfieldguardians","name":"Willfield Guardians","icon":"shield","role":"combat","tagline":"You will not pass. Because I decided.","summary":"Barrier-makers who project their will as force. Willfield Guardians wall off an area, push enemies away and move them wherever the Guardian decides they ought to be.","lore":"They stand with one hand out and refuse to move. The air in front of them hums. Nothing that is pushed back ever argues.","strengths":["Psychic barriers and forced movement","Holds a chokepoint on pure stubbornness"],"weaknesses":["Barriers collapse when the Guardian is hit hard","Very little offense of their own"],"abilities":["Willfield: a wall of force that blocks and pushes","Shove: move an enemy several steps in any direction","Hold Firm: absorb damage with will"],"gear":"Plain armored coat, shield-hand glove, braced boots, rope belt","look":"Broad, powerful woman in a plain armored coat, one gloved palm held out in front of her as a faint shimmer of force pushes back the air, feet braced in a wide stance.","pal":["#f9d634","#ef476f","#eef6ff"]},"meta":{"type":"tank","physique":"broad and powerful","size":"large","move":"grounded","who":"a woman in her forties of Mongolian-inspired features, braced stance"},"spec":{"w":"broad powerful woman in a plain armored coat and a rope belt, one gloved palm held out in front of her, feet braced wide","p":"a narrow stone gate in a canyon with fallen rubble, a rope bridge, a collapsed barricade and a dust-filled corridor"},"cast":{"gender":"Female","ethnicity":"Mongolian heritage, Mongolian","expression":"stubborn, jaw set","pose":"palm out front pushing back the air, stance wide"}},"capacitorhearts":{"leaf":{"id":"capacitorhearts","name":"Capacitor Hearts","icon":"battery","role":"combat","tagline":"Hit me. I'll remember it.","summary":"Fighters who turn damage into power. Capacitor Hearts absorb incoming energy blasts and spend them back, growing brighter with every blow they survive.","lore":"The glow in their chest dims when they are empty and blazes when they are full. They are the most dangerous person in a fight to have hit.","strengths":["Absorbs incoming energy and converts it to power","Tanky, and stronger the longer a fight goes"],"weaknesses":["Weak against non-energy damage","Overloads if overcharged"],"abilities":["Soak: absorb an energy attack and store it","Return Current: spend stored power for a heavy strike","Glowing Chest: a flare that blinds and burns nearby foes"],"gear":"Plain vest, heat-sink gloves, wired belt, minimal boots","look":"Burly, bare-armed young man in an open vest, a glowing circuit-pattern across the chest and forearms, braced mid-block with both fists raised and sparks running off his shoulders.","pal":["#e26b50","#ffd166","#fff5da"]},"meta":{"type":"tank","physique":"burly and bare-armed","size":"large","move":"grounded","who":"a young man in his twenties of Haitian-inspired features, glowing chest circuits"},"spec":{"w":"burly bare-armed young man in an open vest with a glowing circuit pattern across the chest and forearms, braced mid-block with both fists raised","p":"a broken wind-turbine farm with a dead substation, fallen power lines, a rusted pylon and a tangle of cables"},"cast":{"gender":"Male","ethnicity":"Haitian heritage, Haitian","expression":"calm, bright-eyed","pose":"braced with both fists up as sparks run off the shoulders"}},"arcflashstrikers":{"leaf":{"id":"arcflashstrikers","name":"Arcflash Strikers","icon":"bolt","role":"combat","tagline":"Blink and it is already over.","summary":"Mobile fighters who discharge as they move. Arcflash Strikers run on lightning, blinking between positions and striking in a flash.","lore":"Their footprints scorch the ground. Strikers are never in one place long enough to be hit by the same attack twice.","strengths":["Rapid energy discharges and mobility","Hard to pin down and strong in short bursts"],"weaknesses":["Burns out quickly","Little defense"],"abilities":["Arc Blink: teleport along a line of electricity","Flash Strike: a rapid discharge on arrival","Chain Discharge: bounce the strike to nearby enemies"],"gear":"Insulated shoulder cape, sparkgap gloves, plain boots, wrapped knuckles","look":"Wiry person in a short insulated cape mid-dash, both hands crackling with lightning and a line of scorched sparks trailing behind them.","pal":["#fffe64","#ff4d6d","#fff0d1"]},"meta":{"type":"assassin","physique":"wiry and androgynous","size":"medium","move":"agile","who":"a wiry person in their twenties of Peruvian-inspired features, short cropped hair"},"spec":{"w":"wiry person in a short insulated cape, both hands crackling with lightning, a line of scorched sparks trailing behind, no weapons","p":"a thunderstorm rooftop with a lightning-rod forest, scorched concrete, a cracked water tank and arcing cables"},"cast":{"gender":"Nonbinary","ethnicity":"Peruvian heritage, Peruvian","expression":"wild, laughing","pose":"mid-dash with lightning crackling in both hands"}},"resonancebreakers":{"leaf":{"id":"resonancebreakers","name":"Resonance Breakers","icon":"waves","role":"combat","tagline":"I hum a note that ends buildings.","summary":"Overloaders who build up a dangerous resonance and release it in a wave. Resonance Breakers rattle everything in range until it shakes apart.","lore":"They hum while they work, a low note that vibrates in the chest. When the note cracks, everything nearby cracks with it.","strengths":["Dangerous overload and area attacks","Shatters armor and structures"],"weaknesses":["Unstable","Takes damage from their own overload"],"abilities":["Build Resonance: hum a rising note that damages gradually","Shatter Wave: release a shockwave that breaks armor","Critical Mass: overload for a huge, risky area blast"],"gear":"Tuning-fork forearm braces, earplug lanyard, plain tunic, heavy boots","look":"Stocky, middle-aged woman in a plain tunic and heavy boots with tuning-fork braces on both forearms, mouth open on a sustained note and visible shockwave rings spreading out around her.","pal":["#402f7d","#ffbe0b","#e4ffda"]},"meta":{"type":"blaster","physique":"stocky and thick-set","size":"medium","move":"grounded","who":"a woman in her forties of Korean-inspired features, strong jaw"},"spec":{"w":"stocky middle-aged woman in a plain tunic and heavy boots with tuning-fork braces on both forearms, mouth open on a sustained note, shockwave rings spreading","p":"a half-shattered cathedral of glass with cracked stained windows, hanging chandeliers, vibrating dust and a toppled organ"},"cast":{"gender":"Female","ethnicity":"Korean heritage, South Korean","expression":"mouth open on a sustained note","pose":"arms out with tuning-fork braces as shockwave rings spread"}}};
